	DOWN
	LEFT
	RIGHT
	UPLEFT
	UPRIGHT
	DOWNLEFT
	DOWNRIGHT
)

const (
	MAX  = 5*30 + 5
	SIZE = 2 * MAX
)

var dx = [8]int{0, 0, -1, 1, -1, 1, -1, 1}
var dy = [8]int{1, -1, 0, 0, 1, 1, -1, -1}

const stateCount = SIZE * SIZE * 8 * 32 * 6

var marked = make([]uint64, (stateCount+63)/64)
var t [100]int

type point struct {
	x, y int
}

type node struct {
	x, y int
	dir  int
	lev  int
	far  int
}

func stateIndex(x, y, dir, lev, far int) int {
	return (((x*SIZE+y)*8+dir)*32+lev)*6 + far
}

func isMarked(x, y, dir, lev, far int) bool {
	index := stateIndex(x, y, dir, lev, far)
	return marked[index>>6]&(uint64(1)<<uint(index&63)) != 0
}

func mark(x, y, dir, lev, far int) {
	index := stateIndex(x, y, dir, lev, far)
	marked[index>>6] |= uint64(1) << uint(index&63)
}

func rot(dir int) (int, int) {
	switch dir {
	case UP:
		return UPLEFT, UPRIGHT
	case DOWN:
		return DOWNLEFT, DOWNRIGHT
	case LEFT:
		return UPLEFT, DOWNLEFT
	case RIGHT:
		return UPRIGHT, DOWNRIGHT
	case UPLEFT:
		return UP, LEFT
	case UPRIGHT:
		return UP, RIGHT
	case DOWNLEFT:
		return DOWN, LEFT
	case DOWNRIGHT:
		return DOWN, RIGHT
	}
	return 0, 0
}

