	queue = append(queue, node{MAX, MAX, UP, 1, 1})
	mark(MAX, MAX, UP, 1, 1)
	visited[point{MAX, MAX}] = struct{}{}

	ans := 1

	for head := 0; head < len(queue); head++ {
		v := queue[head]

		p := point{v.x, v.y}
		if _, exists := visited[p]; !exists {
			visited[p] = struct{}{}
			ans++
		}

		if v.lev == n+1 {
			continue
		}

		if v.far != t[v.lev] {
			x2 := v.x + dx[v.dir]
			y2 := v.y + dy[v.dir]

